def agent_action(sandbox, agent_body, step_count):
    current_x, current_y = sandbox.get_sled_position()
    current_vx, current_vy = sandbox.get_sled_velocity()

    # Determine current target based on checkpoints
    if not sandbox.get_checkpoint_a_reached():
        target_x, target_y = 18.25, 4.15  # Alpha checkpoint center
    elif not sandbox.get_checkpoint_b_reached():
        target_x, target_y = 23.75, 2.85  # Beta checkpoint center
    else:
        target_x, target_y = 30.0, 2.5  # Final target center

    dx = target_x - current_x
    dy = target_y - current_y
    distance = (dx**2 + dy**2)**0.5

    if distance == 0:
        sandbox.apply_thrust(0, 0)
        return

    # Normalize direction vector
    dir_x = dx / distance
    dir_y = dy / distance

    # Calculate current speed
    current_speed = (current_vx**2 + current_vy**2)**0.5

    # Determine base gain based on distance
    if distance > 20:
        base_gain = 2000
    elif distance > 10:
        base_gain = 1500
    else:
        base_gain = 1000

    # Adjust gain based on current speed
    if current_speed < 1.0:
        gain = base_gain * 2
    elif current_speed > 3.0:
        gain = base_gain * 0.5
    else:
        gain = base_gain

    # Apply main thrust in direction of target
    f1 = gain * dir_x
    f2 = gain * dir_y

    # Adjust vertical thrust based on current y position and target
    if target_y == 4.15:  # Alpha checkpoint (higher y)
        # If too low, apply upward thrust
        if current_y < target_y - 0.5:
            f2 += 500
        elif current_y > target_y + 0.5:
            f2 -= 500
    elif target_y == 2.85:  # Beta checkpoint (mid y)
        # If too low, apply upward thrust
        if current_y < target_y - 0.5:
            f2 += 500
        elif current_y > target_y + 0.5:
            f2 -= 500
    elif target_y == 2.5:  # Final target (lower y)
        # If too high, apply downward thrust
        if current_y > target_y + 0.5:
            f2 -= 500
        elif current_y < target_y - 0.5:
            f2 += 500

    # Apply the thrust
    sandbox.apply_thrust(f1, f2)
